/**
 * A small tinted label. Each tone maps to the one meaning its accent owns on
 * the WP-D palette sheet, so a badge's color is never decorative.
 */

import type { ReactNode } from 'react'

export type BadgeTone = 'neutral' | 'primary' | 'indigo' | 'amber' | 'red' | 'green'

const TONES: Record<BadgeTone, string> = {
  neutral: 'bg-line-soft text-ink-2',
  primary: 'bg-primary-tint text-primary',
  indigo: 'bg-indigo-tint text-indigo-600',
  amber: 'bg-amber-tint text-amber-ink',
  red: 'bg-red-tint text-red-ink',
  green: 'bg-green-tint text-green',
}

export function Badge({ tone = 'neutral', children }: { tone?: BadgeTone; children: ReactNode }) {
  return (
    <span
      className={`inline-flex h-[21px] shrink-0 items-center rounded-[4px] px-2 font-mono text-[10.5px] font-semibold ${TONES[tone]}`}
    >
      {children}
    </span>
  )
}
/**
 * An outbound link. `noreferrer` is not just hygiene here: the app promises it
 * leaks nothing, and a referrer header would quietly tell the destination
 * which page of this tool the reader came from.
 */

import type { ReactNode } from 'react'
import { useTranslation } from 'react-i18next'

export function ExternalLink({ href, children }: { href: string; children: ReactNode }) {
  const { t } = useTranslation()
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer noopener"
      className="text-primary hover:text-primary-strong hover:underline"
    >
      {children}
      <span className="sr-only"> ({t('common.externalLink')})</span>
      <span aria-hidden="true"> ↗</span>
    </a>
  )
}

export const REPO_URL = 'https://github.com/cebert/cache-ttl-analyzer'
export const CLAUDE_CODE_DOCS_URL = 'https://docs.claude.com/en/docs/claude-code'
